const format = (n) => new Intl.NumberFormat("en", { notation: "compact" }).format(n);

/** Lifetime tokens generated by all models. Hover for the split per model. */
export default function UsageLine({ models }) {
  const generated = models.reduce((sum, m) => sum + m.completion_tokens, 0);
  const prompt    = models.reduce((sum, m) => sum + m.prompt_tokens, 0);
  const details   = models
    .map((m) => `${m.model}: ${m.completion_tokens} out · ${m.prompt_tokens} in`)
    .join("\n");

  return (
    <div className="usage" title={details}>
      <span className="usage-icon">◈</span>
      <span className="usage-stat">
        <span className="usage-value">{format(generated)}</span>
        <span className="usage-key"> tokens out</span>
      </span>
      {prompt > 0 && (
        <span className="usage-stat">
          <span className="usage-value">{format(prompt)}</span>
          <span className="usage-key"> in</span>
        </span>
      )}
    </div>
  );
}
